import {shouldContinueToolLoop, accumulateUsage} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('accumulateUsage', () => {
  it('sums token counts across defined rounds, keeps a running total past an unreported round, and stays undefined when neither reported', () => {
    const first = accumulateUsage(undefined, {inputTokens: 100, outputTokens: 10, totalTokens: 110});
    const afterUnreported = accumulateUsage(first, undefined);
    const afterSecond = accumulateUsage(afterUnreported, {inputTokens: 200, outputTokens: 20, totalTokens: 220});

    expect({
      none: accumulateUsage(undefined, undefined),
      first,
      afterUnreported,
      afterSecond,
    }).toEqual({
      none: undefined,
      first: {inputTokens: 100, outputTokens: 10, totalTokens: 110},
      afterUnreported: {inputTokens: 100, outputTokens: 10, totalTokens: 110},
      afterSecond: {inputTokens: 300, outputTokens: 30, totalTokens: 330},
    });
  });
});

export function extractStopReason(chunk: MessageChunk): string | null {
  return chunk.type === 'stop' ? chunk.stopReason : null;
}

export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
  return chunk.type === 'stop' ? chunk.usage : undefined;
}

export function accumulateUsage(
  total: UsageMetadata | undefined,
  round: UsageMetadata | undefined
): UsageMetadata | undefined {
  if (!round) return total;
  if (!total) return round;
  return {
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  };
}

